from taf.gnb.oam.coam.cu.utilities.http_client import HttpClient


class TRSv1HttpClient(HttpClient):
    """ This class provides a client for the TRS v1 API. """

    def __init__(self, base_url, connection_alias):
        super(TRSv1HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/trs/v1"

    def get_external_interfaces_of_pmtu_discovery(self, timeout=30):
        endpoint = '/interfaces/external'
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def start_ip_connectivity_test(self, ping_test_setup, timeout=30):
        endpoint = '/test/ip-connectivity'
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_post_request(endpoint=endpoint, timeout=timeout, headers=headers, json=ping_test_setup)

    def start_ip_reachability_test(self, timeout=30):
        endpoint = '/test/ip-reachability-test'
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_post_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def get_ip_reachability_test_status(self, operation_id, timeout=30):
        endpoint = f'/test/ip-reachability-test/{operation_id}'
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def get_uplane_configuration(self, timeout):
        endpoint = "/traces/common-configuration"
        headers = {
            "accept": "application/json"
        }

        return self._send_get_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def update_uplane_configuration(self, ip_address, port, dscp, timeout):
        endpoint = "/traces/common-configuration"
        headers = {
            "accept": "application/json",
            "Content-Type": "application/json"
        }

        json_data = {
            'uplaneIpAddress': ip_address,
            'uplanePort': port,
            'dscp': dscp,
            'traceType': 'UPlane',
        }

        return self._send_put_request(endpoint=endpoint, json=json_data, timeout=timeout, headers=headers)

    def get_trs_operation_status(self, operation_id, timeout=30):
        endpoint = f'/operations/{operation_id}'
        headers = {
            "accept": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def get_ip_connectivity_test_result(self, operation_id, timeout=30):
        endpoint = f'/test/ip-connectivity/{operation_id}'
        headers = {
            "accept": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def update_cu_psk_configuration(self, password, timeout=30):
        endpoint = "/security/presharedkey"
        headers = {
            "accept": "application/json",
            "Content-Type": "application/json"
        }

        json_data = {
            'password': password,
        }

        return self._send_post_request(endpoint=endpoint, json=json_data, timeout=timeout, headers=headers)

    def start_pmtu_discovery(self, name, source_ip, destination_ip, dscp, timeout=30):
        endpoint = "/test/pmtu-discovery"
        headers = {
            "Content-Type": "application/json",
            "accept": "application/json",
        }

        json_data = {
            'name': name,
            'sourceIp': source_ip,
            'destinationIp': destination_ip,
            'dscp': dscp,
        }

        return self._send_post_request(endpoint=endpoint, json=json_data, timeout=timeout, headers=headers)

    def get_ip_security_associations(self, policy_id, tnl_pod_hostname, timeout=30):
        endpoint = '/security/ike-policies'
        headers = {
            "accept": "application/json",
        }

        params = {
            'policyId': policy_id,
            'tnlPodHostname': tnl_pod_hostname,
        }

        return self._send_get_request(endpoint=endpoint, payload=params, timeout=timeout, headers=headers)

    def get_pmtu_discovery_status(self, operation_id, timeout=30):
        endpoint = f'/test/pmtu-discovery/{operation_id}'
        headers = {
            "accept": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, timeout=timeout, headers=headers)
